  },
  "hints": [
    {
      "cue": "Đặt $m = kn$",
      "explanation": "Bạn hãy đặt $m = kn$ với $k$ là số nguyên dương. Việc này sẽ giúp ta thay thế $m$ bằng một biểu thức chỉ chứa $n$ và $k$.",
      "focus": [],
      "id": "hint_1",
      "level": 1,
      "math": "m = kn \\quad (k \\in \\mathbb{Z}^+)",
      "question": "Vì $m$ chia hết cho $n$, bạn có thể biểu diễn $m$ theo $n$ như thế nào để đơn giản hóa bài toán?",
      "stepId": 
    "step_1"
    },
    {
      "cue": "Chia tử và mẫu cho $n^2$",
      "explanation": "Khi thay vào và rút gọn, bạn sẽ thấy biểu thức tách thành một phần nguyên $k$ và hai phân số $\\frac{1}{n} + \\frac{1}{k}$. Để tổng ban đầu là số nguyên, phần $\\frac{1}{n} + \\frac{1}{k}$ cũng phải là số nguyên.",
      "focus": [],
      "id": "hint_2",
      "level": 2,
      "math": "\\frac{m^2+m+n^2}{mn} = k + \\frac{1}{n} + \\frac{1}{k}",
      "question": "Thay $m = kn$ vào biểu thức $\\frac{m^2+m+n^2}{mn}$, bạn sẽ rút gọn được kết quả như thế nào?",
      "stepId": "step_2"
    },
    {
      "cue": "Đánh giá chặn $\\frac{1}{n} \\le 1$ và $\\frac{1}{k} \\le 1$",
      "explanation": "Vì $n, k \\ge 1$ nên $\\frac{1}{n} \\le 1$ và $\\frac{1}{k} \\le 1$. Tổng của chúng không vượt quá 2. Do đó, tổng này chỉ có thể là 1 hoặc 2. Bạn hãy xét từng trường hợp để tìm $n$ và $k$ nhé!",
      "focus": [],
      "id": "hint_3",
      "level": 3,
      "math": "0 < \\frac{1}{n} + \\frac{1}{k} \\le 2",
      "question": "Với $n, k$ là các số nguyên dương, tổng $\\frac{1}{n} + \\frac{1}{k}$ có thể nhận những giá trị nguyên nào?",
      "stepId": "step_3"
    }
  ],
  "steps": [
    {
      "explanation": "Vì $m$ chia hết cho $n$, ta có thể viết $m$ dưới dạng $kn$ với $k$ là số nguyên dương.",
      "geometryActions": [],
      "id": "step_1",
      "math": "m = kn \\quad (k \\in \\mathbb{Z}^+)",
      "reason": "Định nghĩa chia hết",
      "title": "Đặt ẩn phụ theo điều kiện chia hết",
      "uses": []
    },
    {
      "explanation": "Thay $m = kn$ vào phân thức $\\frac{m^2+m+n^2}{mn}$ và rút gọn, ta thấy phần nguyên $k$ luôn là số nguyên, nên phần còn lại $\\frac{1}{n} + \\frac{1}{k}$ cũng phải là số nguyên.",
      "geometryActions": [],
      "id": "step_2",
      "math": "\\frac{m^2+m+n^2}{mn} = \\frac{k^2n^2+kn+n^2}{kn^2} = k + \\frac{1}{n} + \\frac{1}{k}",
      "reason": "Biến đổi đại số",
      "title": "Thay vào điều kiện chia hết",
      "uses": [
        "step_1"
      ]
    },
    {
      "explanation": "Vì $n, k \\ge 1$ nên $\\frac{1}{n} \\le 1$ và $\\frac{1}{k} \\le 1$, suy ra $0 < \\frac{1}{n} + \\frac{1}{k} \\le 2$. Để tổng này là số nguyên, nó chỉ có thể bằng 1 hoặc 2.",
      "geometryActions": [],
      "id": "step_3",
      "math": "0 < \\frac{1}{n} + \\frac{1}{k} \\le 2",
      "reason": "Đánh giá chặn",
      "title": "Đánh giá chặn để tìm $k$ và $n$",
      "uses": [
        "step_2"
      ]
    },
    {
      "explanation": "Nếu tổng bằng 2 thì $n=1, k=1 \\Rightarrow m=1$. Nếu tổng bằng 1 thì $\\frac{n+k}{nk}=1 \\Rightarrow (n-1)(k-1)=1 \\Rightarrow n=2, k=2 \\Rightarrow m=4$. Cả hai bộ $(1,1)$ và $(4,2)$ đều thỏa mãn đề bài.",
      "geometryActions": [],
      "id": "step_4",
      "math": "\\begin{cases} n=1, k=1 \\Rightarrow m=1 \\ n=2, k=2 \\Rightarrow m=4 \\end{cases}",
      "reason": "Giải phương trình nghiệm nguyên",
      "title": "Giải từng trường hợp và kết luận",
      "uses": [
        "step_3"
      ]
    }
  ],
  "strategy": "Dùng điều kiện $m \\vdots n$ để đặt $m = kn$, thay vào điều kiện chia hết để tìm quan hệ giữa $k$ và $n$, sau đó dùng đánh giá chặn để tìm nghiệm nguyên."
